From c698a7fba20213aff8c80b51ca5dbf1f46b2520b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:39:40 +0100
Subject: [PATCH] shell/panelview: Ignore the Leave event sent when a panel
 menu opens

Qt sends a panel a Leave when its menu grabs the pointer, and no Enter
after it closes, so auto-hide hid the panel under the pointer. Ignore
that Leave, and keep the panel as the Global Menu's transient parent.

BUG: 473454
---
 applets/appmenu/appmenuapplet.cpp |  8 +++++++-
 shell/panelview.cpp               | 14 ++++++++++++++
 shell/panelview.h                 |  1 +
 3 files changed, 22 insertions(+), 1 deletion(-)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..01db0b5e65 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -191,7 +191,11 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)

         if (view() == FullView) {
             if (!m_currentMenu) {
-                m_currentMenu = new QMenu(qobject_cast<QWidget *>(actionMenu->parent()));
+                // not a child of the application's menu, or QMenu would replace the panel as its transient parent
+                m_currentMenu = new QMenu;
+                connect(actionMenu->parent(), &QObject::destroyed, m_currentMenu, [menu = m_currentMenu.data()] {
+                    delete menu;
+                });
                 connect(m_currentMenu, &QMenu::aboutToHide, this, &AppMenuApplet::onMenuAboutToHide, Qt::UniqueConnection);
             } else if (m_sourceMenu != actionMenu) {
                 auto menuAction = m_currentMenu->menuAction();
@@ -246,6 +250,8 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)
                 // don't try to popup an empty menu in case the app gives us one
                 return;
             }
+            m_currentMenu->winId(); // create window handle
+            m_currentMenu->windowHandle()->setTransientParent(ctx->window());
             m_currentMenu->popup(pos);
             connect(actionMenu, &QMenu::aboutToHide, this, &AppMenuApplet::onMenuAboutToHide, Qt::UniqueConnection);
         }
diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..3cf0b972a9 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -1181,6 +1181,20 @@ bool PanelView::event(QEvent *e)
         break;

     case QEvent::Leave:
+        // Qt sends a Leave when a popup of the panel grabs the pointer, even though it is still on the panel,
+        // and no Enter when the popup closes, as it only does that for xdg-shell parents
+        if (m_containsMouse && !m_popupGrabWatcher) {
+            const auto windows = qApp->topLevelWindows();
+            const auto popup = std::ranges::find_if(windows, [this](QWindow *window) {
+                return window->type() == Qt::Popup && window->transientParent() == this && window->isVisible();
+            });
+            if (popup != windows.end()) {
+                m_popupGrabWatcher = connect(*popup, &QWindow::visibleChanged, this, [this] {
+                    disconnect(m_popupGrabWatcher);
+                });
+                break;
+            }
+        }
         m_containsMouse = false;
         if (edgeActivated()) {
             m_unhideTimer.start();
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..a2c3bd465d 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -366,6 +366,7 @@ private:
     QPointer<QScreen> m_lastScreen;
     QPointer<QScreen> m_screenToFollow;
     QMetaObject::Connection m_transientWindowVisibleWatcher;
+    QMetaObject::Connection m_popupGrabWatcher;
     AutoHideScreenEdge *m_autoHideScreenEdge = nullptr;

     static const int STRUTSTIMERDELAY = 200;
